ln, _ := net.Listen("tcp", ":8080")
sem := make(chan struct{}, 1024)          // bound the pool, not the threads
for {
    c, err := ln.Accept()
    if err != nil { continue }
    sem <- struct{}{}
    go func(c net.Conn) {
        defer func() { <-sem; c.Close() }()
        serve(c)                          // blocking style over the netpoller
    }(c)
}
